using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

public static class CoroutineUtility
{
	public static List<Transform> shakingTransforms = new List<Transform>();

	public static Coroutine WaitUntil(MonoBehaviour mono, Func<bool> func, float delay, UnityAction action)
	{
		return mono.StartCoroutine(WaitUntil_Routine(func, delay, action));
	}

	public static Coroutine WaitUntil(MonoBehaviour mono, Func<bool> func, UnityAction action)
	{
		return mono.StartCoroutine(WaitUntil_Routine(func, 0f, action));
	}

	public static IEnumerator WaitUntil_Routine(Func<bool> func, float delay, UnityAction action)
	{
		yield return new WaitUntil(func);
		yield return new WaitForSeconds(delay);
		action.Execute();
	}

	public static IEnumerator WaitUntil_Routine(Func<bool> func, Action action)
	{
		yield return new WaitUntil(func);
		action?.Invoke();
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action startAction, Action<float, float> midAction, Action endAction, bool isRealtime)
	{
		startAction?.Invoke();
		float t2 = 0f;
		while (t2 < 1f)
		{
			t2 += (isRealtime ? Time.unscaledDeltaTime : Time.deltaTime) / duration;
			t2 = Mathf.Clamp01(t2);
			midAction?.Invoke(t2, curve.Evaluate(t2));
			yield return InvokeAlternatives.WaitOneFrame();
		}
		endAction?.Invoke();
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action startAction, Action<float, float> midAction, Action endAction)
	{
		return CurveRoutine(duration, curve, startAction, midAction, endAction, isRealtime: false);
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action startAction, Action<float, float> midAction)
	{
		return CurveRoutine(duration, curve, startAction, midAction, null);
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action<float, float> midAction, Action endAction, bool isRealtime = false)
	{
		return CurveRoutine(duration, curve, null, midAction, endAction, isRealtime);
	}

	public static IEnumerator CurveRoutine(float duration, Action<float, float> midAction, Action endAction)
	{
		return CurveRoutine(duration, LinearCurve(), null, midAction, endAction, isRealtime: false);
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action<float, float> midAction)
	{
		return CurveRoutine(duration, curve, null, midAction, null);
	}

	public static IEnumerator CurveRoutine(float duration, Action<float, float> midAction, bool isRealtime)
	{
		return CurveRoutine(duration, LinearCurve(), null, midAction, null, isRealtime);
	}

	public static IEnumerator CurveRoutine(float duration, AnimationCurve curve, Action<float, float> midAction, bool isRealtime)
	{
		return CurveRoutine(duration, curve, null, midAction, null, isRealtime);
	}

	public static IEnumerator CurveRoutine(float duration, Action<float, float> midAction)
	{
		return CurveRoutine(duration, midAction, isRealtime: false);
	}

	public static IEnumerator MoveRoutineWithArc(float duration, AnimationCurve curve, Action startAction, Transform transform, Vector3 startPosition, Vector3 targetPosition, float arcHeight, AnimationCurve arcCurve, Action endAction)
	{
		Action<float, float> midAction = delegate(float t, float v)
		{
			transform.position = Vector3.Lerp(startPosition, targetPosition, v) + Vector3.up * arcHeight * arcCurve.Evaluate(t);
		};
		return CurveRoutine(duration, curve, startAction, midAction, endAction, isRealtime: false);
	}

	public static IEnumerator MoveRoutineWithArc(float duration, AnimationCurve curve, Action startAction, Transform transform, Vector3 startPosition, Vector3 targetPosition, float arcHeight, Action endAction)
	{
		return MoveRoutineWithArc(duration, curve, startAction, transform, startPosition, targetPosition, arcHeight, GetDefaultArcCurve(), endAction);
	}

	private static AnimationCurve GetDefaultArcCurve()
	{
		Keyframe[] obj = new Keyframe[3]
		{
			new Keyframe(0f, 0f),
			default(Keyframe),
			default(Keyframe)
		};
		obj[0].outTangent = 5f;
		obj[1] = new Keyframe(0.5f, 1f);
		obj[1].inTangent = 0f;
		obj[1].outTangent = 0f;
		obj[2] = new Keyframe(1f, 0f);
		obj[2].inTangent = -5f;
		return new AnimationCurve(obj);
	}

	public static IEnumerator ShakeRoutineEnumerator(Transform transformToShake, float shakeDuration, float shakePower, Action afterShakeAction = null)
	{
		Vector3 pos = transformToShake.localPosition;
		Vector2 shakeVector;
		yield return CurveRoutine(shakeDuration, GetDefaultShakeCurve(), delegate(float t, float value)
		{
			shakeVector = new Vector2(UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f));
			if (shakeVector.magnitude > 1f)
			{
				shakeVector = shakeVector.normalized;
			}
			shakeVector *= value * shakePower;
			transformToShake.localPosition = pos + (Vector3)shakeVector;
		}, delegate
		{
			transformToShake.localPosition = pos;
			shakingTransforms.Remove(transformToShake);
			afterShakeAction?.Invoke();
		});
	}

	public static void ShakeRoutine(MonoBehaviour mono, Transform transformToShake, float shakeDuration, float shakePower, AnimationCurve shakeCurve, Action afterShakeAction = null)
	{
		if (shakingTransforms.Contains(transformToShake))
		{
			return;
		}
		shakingTransforms.Add(transformToShake);
		Vector3 pos = transformToShake.localPosition;
		Vector2 shakeVector;
		mono.StartCoroutine(CurveRoutine(shakeDuration, shakeCurve, delegate(float t, float value)
		{
			shakeVector = new Vector2(UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f));
			if (shakeVector.magnitude > 1f)
			{
				shakeVector = shakeVector.normalized;
			}
			shakeVector *= value * shakePower;
			transformToShake.localPosition = pos + (Vector3)shakeVector;
		}, delegate
		{
			transformToShake.localPosition = pos;
			shakingTransforms.Remove(transformToShake);
			afterShakeAction?.Invoke();
		}));
	}

	public static void ShakeRoutine(MonoBehaviour mono, Transform transformToShake, float shakeDuration, float shakePower)
	{
		ShakeRoutine(mono, transformToShake, shakeDuration, shakePower, GetDefaultShakeCurve());
	}

	private static AnimationCurve GetDefaultShakeCurve()
	{
		Keyframe[] obj = new Keyframe[2]
		{
			new Keyframe(0f, 1f),
			default(Keyframe)
		};
		obj[0].outTangent = 0f;
		obj[1] = new Keyframe(1f, 0f);
		obj[1].inTangent = -2.3f;
		return new AnimationCurve(obj);
	}

	public static void ShakeRoutine(MonoBehaviour mono, Transform transformToShake)
	{
		float shakeDuration = 0.5f;
		float shakePower = 6f;
		ShakeRoutine(mono, transformToShake, shakeDuration, shakePower, GetDefaultShakeCurve());
	}

	public static void ShakeRoutine(MonoBehaviour mono, Transform transformToShake, Action afterShakeAction)
	{
		float shakeDuration = 0.5f;
		float shakePower = 6f;
		ShakeRoutine(mono, transformToShake, shakeDuration, shakePower, GetDefaultShakeCurve(), afterShakeAction);
	}

	public static AnimationCurve LinearCurve()
	{
		AnimationCurve animationCurve = new AnimationCurve();
		animationCurve.AddKey(0f, 0f);
		animationCurve.AddKey(1f, 1f);
		return animationCurve;
	}
}
